def backfill_receipts(apps, schema_editor):
    """Give payments recorded before receipts existed a token and a receipt number."""
    Payment = apps.get_model("payments", "Payment")
    Sequence = apps.get_model("invoices", "InvoiceSequence")
    for p in Payment.objects.order_by("created_at", "id"):
        year = p.paid_on.year
        seq, _ = Sequence.objects.get_or_create(business_id=p.business_id, prefix="RCT", year=year)
        seq.last_number += 1
        seq.save(update_fields=["last_number"])
        p.public_token = uuid.uuid4()
        p.receipt_number = f"RCT-{year}-{seq.last_number:04d}"
        p.save(update_fields=["public_token", "receipt_number"])


